#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

long long solve(const vector<long long>& nums) {
    int n = nums.size();
    long long total = 0;

    // 计算数组总和
    for (long long x : nums) {
        total += x;
    }

    // 总和为奇数时，不可能分成两段和相等
    if (total % 2 != 0) {
        return 0;
    }

    long long target = total / 2;
    long long pre = 0;
    long long ans = 0;

    // 哈希表记录前缀和出现次数
    unordered_map<long long, long long> cnt;
    cnt[0] = 1; // 初始前缀和为0

    // 只枚举到 n-1，保证两段都非空
    for (int i = 0; i < n - 1; i++) {
        pre += nums[i]; // 当前前缀和

        // 统计满足条件的前缀和个数
        if (cnt.count(pre - target)) {
            ans += cnt[pre - target];
        }

        // 记录当前前缀和
        cnt[pre]++;
    }

    return ans;
}

int main() {
    int n;
    cin >> n;

    vector<long long> nums(n);
    for (int i = 0; i < n; i++) {
        cin >> nums[i];
    }

    cout << solve(nums) << endl;
    return 0;
}
